  h.card.setOnLongClickListener(selecting||row.entry==null?null:v->{enterSelection(keys(row));return true;});
  h.title.setText(row.title);h.preview.setText(row.preview);h.preview.setVisibility(row.preview.isEmpty()?View.GONE:View.VISIBLE);h.card.setContentDescription(row.description);h.card.setFocusable(true);
  if(row.type==Row.PART){h.number.setText(Integer.toString(row.number));h.range.setText(row.start+"–"+row.end);h.card.setBackground(MaterialReadingUI.pressable(a,MaterialReadingUI.corners(a,MaterialReadingUI.CARD,0,row.last?16:0)));MaterialCatalog.Entry part=row.entry;h.card.setOnClickListener(v->{if(selecting)toggle(row);else open(part);});return;}
  h.start.setText(row.start);h.end.setText(row.end);h.meta.setText(row.meta);h.meta.setTextColor(row.metaColor);
  if(row.type==Row.HEAD){h.chevron.rotate(row.open?180:0);h.card.setBackground(MaterialReadingUI.pressable(a,MaterialReadingUI.corners(a,MaterialReadingUI.CARD,16,row.open?0:16)));String key=row.key;h.chevron.setVisibility(selecting?View.GONE:View.VISIBLE);h.card.setOnClickListener(v->{if(selecting){toggle(row);return;}if(!expanded.remove(key))expanded.add(key);rebuildRows();});return;}
  h.card.setBackground(MaterialReadingUI.pressable(a,MaterialReadingUI.fill(a,MaterialReadingUI.CARD,16)));MaterialCatalog.Entry entry=row.entry;h.card.setOnClickListener(v->{if(selecting)toggle(row);else open(entry);});
