 /** Flatten the selected day into rows; the list keeps its scroll position across updates. */
 private void rebuildRows(){rows.clear();if(snapshot==null){adapter.notifyDataSetChanged();return;}MaterialCatalog catalog=snapshot.catalog;ZoneId zone=catalog.zone;List<MaterialCatalog.Entry> entries=catalog.on(selected);
  for(MaterialTimeline.Section section:MaterialTimeline.sections(MaterialTimeline.items(entries,snapshot.insights,selected.toString(),zone.getId()),zone,newestFirst)){
   Row label=new Row(Row.SECTION);label.title=section.name;label.meta=section.count()+" 条";rows.add(label);
   for(MaterialTimeline.Item item:section.items){
    if(!item.group()){MaterialCatalog.Entry entry=item.parts.get(0);Row r=new Row(Row.SINGLE);r.entry=entry;r.start=clock(item.start,zone);r.end=clock(item.end,zone);r.title=item.title();r.preview=item.summary().isEmpty()?firstText(entry):MaterialReadingUI.plain(item.summary());r.meta=minutes(item.start,item.end)+" 分钟"+(hasTrail(item.start,item.end)?" · 有位置":"")+" · "+shortSync(entry);r.metaColor=AgentUI.MUTED;r.description=r.title+"，"+r.start+"到"+r.end+"，"+shortSync(entry);rows.add(r);continue;}
    Row head=new Row(Row.HEAD);head.entry=item.parts.get(0);head.parts=item.parts;head.key=item.parts.get(0).id;head.open=selecting||expanded.contains(head.key);head.start=clock(item.start,zone);head.end=clock(item.end,zone);head.title=item.title();head.preview=MaterialReadingUI.plain(item.summary());head.meta="连续记录 "+item.parts.size()+" 段 · "+minutes(item.start,item.end)+" 分钟"+(hasTrail(item.start,item.end)?" · 有位置":"");head.description=head.title+"，"+item.parts.size()+" 段，"+(head.open?"已展开":"已收起");rows.add(head);
    if(!head.open)continue;List<MaterialCatalog.Entry> parts=new ArrayList<>(item.parts);if(newestFirst)Collections.reverse(parts);
    for(int i=0;i<parts.size();i++){MaterialCatalog.Entry part=parts.get(i);Row r=new Row(Row.PART);r.entry=part;r.number=item.parts.indexOf(part)+1;r.last=i==parts.size()-1;r.title=part.title;r.start=clock(MaterialTimeline.start(part),zone);r.end=clock(MaterialTimeline.end(part),zone);r.preview=firstText(part);r.description="第 "+r.number+" 段，"+part.title+"，"+r.start+"到"+r.end;rows.add(r);}
   }
  }
  Row footer=new Row(Row.FOOTER);footer.title="日期按手机时区："+zone.getId()+"。服务器仅同步每日 AI 总结。转写、原音和位置保留在手机。资料卡右滑导出，左滑多选或删除；长按也可进入多选。";rows.add(footer);adapter.notifyDataSetChanged();
 }
