 // Selection: the chosen set holds entry ids of the selected day; a group head stands for all its parts.
 private static List<String> keys(Row row){if(row.type==Row.HEAD){List<String> ids=new ArrayList<>();for(MaterialCatalog.Entry e:row.parts)ids.add(e.id);return ids;}return row.entry==null?Collections.emptyList():Collections.singletonList(row.entry.id);}
 private static boolean pickable(Row row){return row.type==Row.SINGLE||row.type==Row.HEAD||row.type==Row.PART;}
 private int tickState(Row row){List<String> ids=keys(row);int n=0;for(String id:ids)if(chosen.contains(id))n++;return n==0?MaterialReadingUI.Tick.NONE:n==ids.size()?MaterialReadingUI.Tick.ALL:MaterialReadingUI.Tick.SOME;}
 private void toggle(Row row){if(tickState(row)==MaterialReadingUI.Tick.ALL)chosen.removeAll(keys(row));else chosen.addAll(keys(row));updateSelection();}
 private List<MaterialCatalog.Entry> dayEntries(){return snapshot==null?Collections.emptyList():snapshot.catalog.on(selected);}
 private boolean everything(){List<MaterialCatalog.Entry> day=dayEntries();if(day.isEmpty())return false;for(MaterialCatalog.Entry e:day)if(!chosen.contains(e.id))return false;return true;}
