 /** Press in the tick column and drag to give every row passed the first row's new state; the list scrolls at its edges. */
 private final class SelectFrame extends FrameLayout {
  private final int slop=ViewConfiguration.get(activity).getScaledTouchSlop(),edge=AgentUI.dp(activity,64);private boolean armed,dragging,target;private float downY;private int anchor=-1;private Set<String> before=Collections.emptySet();
  SelectFrame(){super(activity);}
  void cancelDrag(){armed=dragging=false;anchor=-1;before=Collections.emptySet();}
  private int rowAt(float y){int pos=list.pointToPosition(list.getWidth()/2,(int)y);int i=pos-list.getHeaderViewsCount();return pos==AdapterView.INVALID_POSITION||i<0||i>=rows.size()?-1:i;}
  @Override public boolean onInterceptTouchEvent(MotionEvent e){if(!selecting)return false;
   switch(e.getActionMasked()){
    case MotionEvent.ACTION_DOWN:dragging=false;anchor=rowAt(e.getY());armed=e.getX()<list.getPaddingLeft()+AgentUI.dp(activity,92)&&anchor>=0&&pickable(rows.get(anchor));downY=e.getY();return false;
    case MotionEvent.ACTION_MOVE:if(armed&&!dragging&&Math.abs(e.getY()-downY)>slop){dragging=true;target=tickState(rows.get(anchor))!=MaterialReadingUI.Tick.ALL;before=new HashSet<>(chosen);apply(e.getY());return true;}return dragging;
    default:return dragging;
   }}
  @Override public boolean onTouchEvent(MotionEvent e){if(!dragging)return false;
   switch(e.getActionMasked()){
    case MotionEvent.ACTION_MOVE:{float y=e.getY();int bottom=getHeight()-(bar.getVisibility()==View.VISIBLE?bar.getHeight():0);if(y<edge)list.scrollListBy(-edge/4);else if(y>bottom-edge)list.scrollListBy(edge/4);apply(y);return true;}
    case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:dragging=armed=false;return true;
    default:return true;
   }}
  private void apply(float y){int to=rowAt(y);if(to<0)return;chosen.clear();chosen.addAll(before);for(int i=Math.min(anchor,to);i<=Math.max(anchor,to);i++){Row r=rows.get(i);if(!pickable(r))continue;if(target)chosen.addAll(keys(r));else chosen.removeAll(keys(r));}updateSelection();}
 }
 private List<MaterialTimeline.Item> dayItems(){List<MaterialTimeline.Item> items=new ArrayList<>(MaterialTimeline.items(dayEntries(),snapshot.insights,selected.toString(),snapshot.catalog.zone.getId()));items.sort(Comparator.comparingLong(i->i.start));return items;}
 /** A whole event becomes one document when every part of it is chosen; otherwise each chosen part is its own. */
 private void exportChosen(){if(snapshot==null)return;List<MaterialDocumentExport.Job> jobs=new ArrayList<>();
  for(MaterialTimeline.Item item:dayItems()){List<MaterialCatalog.Entry> picked=new ArrayList<>();for(MaterialCatalog.Entry e:item.parts)if(chosen.contains(e.id))picked.add(e);if(picked.isEmpty())continue;
   if(item.group()&&picked.size()==item.parts.size()&&item.event!=null)jobs.add(new MaterialDocumentExport.Job(item.parts.get(0),item.event,true));else for(MaterialCatalog.Entry e:picked)jobs.add(new MaterialDocumentExport.Job(e,item.event,false));}
  MaterialDocumentExport.summaries(activity,snapshot.catalog.account,jobs);leaveSelection(true);}
 private void audioSheet(Collection<String> initial){if(snapshot==null)return;String account=snapshot.catalog.account;MaterialBatch.audio(activity,dayItems(),snapshot.catalog.zone,new LinkedHashSet<>(initial),picked->{MaterialAudioExport.saveAll(activity,account,picked);leaveSelection(true);});}
 /** Lists every official event of the day; the ones touching the chosen rows start ticked. */
 private void deleteSheet(Collection<String> initial){if(snapshot==null)return;if(snapshot.insights==null){AgentUI.notice(activity,"这一天的记录尚未对应到原厂智记，请刷新后再试");return;}
  List<MaterialBatch.Choice> choices=new ArrayList<>();Set<String> ticked=new LinkedHashSet<>();int unmatched=0;
  for(MaterialTimeline.Item item:dayItems()){int picked=0;for(MaterialCatalog.Entry e:item.parts)if(initial.contains(e.id))picked++;
   if(item.event==null){unmatched+=picked;continue;}choices.add(new MaterialBatch.Choice(item.event,item.start,item.end,Math.max(item.event.refs.size(),item.parts.size()),picked));if(picked>0)ticked.add(item.event.id);}
  if(choices.isEmpty()){AgentUI.notice(activity,"这一天的记录尚未对应到可删除的原厂智记，请刷新后再试");return;}
  MaterialBatch.delete(activity,choices,ticked,snapshot.catalog.zone,unmatched,this::deleteEvents);}
 /** Deletes one event at a time against the latest verified snapshot; stops at the first unconfirmed result. */
 private void deleteEvents(List<OfficialLifelogInsight.Event> events){if(snapshot==null)return;String date=selected.toString(),timezone=snapshot.catalog.zone.getId();Toast.makeText(activity,"正在删除 "+events.size()+" 条原厂智记…",Toast.LENGTH_SHORT).show();int[] done={0};Runnable[] next={null};
  next[0]=()->{if(closed||suspended||snapshot==null)return;if(done[0]>=events.size()){leaveSelection(false);render();AgentUI.notice(activity,done[0]==1?"原厂智记已删除":"已删除 "+done[0]+" 条原厂智记");return;}
   runtime.deleteEvent(snapshot,events.get(done[0]),date,timezone,(value,error)->{if(closed||suspended)return;if(!error.isEmpty()){leaveSelection(true);AgentUI.notice(activity,(done[0]>0?"已删除 "+done[0]+" 条；":"")+"第 "+(done[0]+1)+" 条未能确认删除结果，请刷新核对；不会自动重试删除");return;}snapshot=value;done[0]++;next[0].run();});};
  next[0].run();}
 private void open(MaterialCatalog.Entry selectedEntry){if(snapshot==null||suspended||openedDetail!=null&&openedDetail.dialog.isShowing())return;MaterialRuntime.CatalogSnapshot selectedSnapshot=snapshot;AgentUI.Screen screen=new AgentUI.Screen(activity,"智记详情");openedDetail=screen;trackSensitive(screen.dialog);screen.body.addView(AgentUI.text(activity,"正在核对账号…",14,AgentUI.MUTED));runtime.verifyCatalog(selectedSnapshot,(value,error)->{
  if(closed||suspended||!screen.dialog.isShowing()||activity.isDestroyed())return;if(!error.isEmpty()||value==null){screen.dialog.dismiss();AgentUI.notice(activity,MaterialWorkspace.label(error));refresh();return;}
  for(MaterialCatalog.Entry current:value.catalog.entries)if(current==selectedEntry){detail(screen,value,current);return;}screen.dialog.dismiss();AgentUI.notice(activity,"这条记录已不在当前资料列表中，请刷新后查看。");refresh();
 });}
 /** Parts of the same official event, in time order; just the entry when it stands alone. */
 private static List<MaterialCatalog.Entry> siblings(MaterialRuntime.CatalogSnapshot value,OfficialLifelogInsight.Event event,MaterialCatalog.Entry entry){if(event==null||value.insights==null)return Collections.singletonList(entry);Set<String> ids=value.insights.materialIds(event);List<MaterialCatalog.Entry> found=new ArrayList<>();for(MaterialCatalog.Entry e:value.catalog.entries)if(ids.contains(e.id))found.add(e);if(!found.contains(entry))found.add(entry);found.sort(MaterialTimeline.CHRONOLOGICAL);return found;}
