 /** Open the transcript fold, page far enough to include the target, then scroll to it. */
 private void reveal(AgentUI.Screen screen,MaterialReadingUI.Fold fold,List<View> rows,Runnable[] more,int target){if(fold==null)return;if(!fold.isOpen())fold.set(true);while(rows.size()<=target){int before=rows.size();more[0].run();if(rows.size()==before)return;}View row=rows.get(target);screen.scroll.post(()->{int y=0;for(View v=row;v!=null&&v!=screen.body;v=(View)v.getParent())y+=v.getTop();screen.scroll.smoothScrollTo(0,Math.max(0,y-AgentUI.dp(activity,12)));});}
 /** Keep initial Android text measurement bounded. Export/delegation retain the
  * complete immutable entry; expanding the reading view never truncates it. */
 private void appendText(LinearLayout content,String text){if(text.isEmpty()){content.addView(AgentUI.text(activity,"暂无转写正文",16,AgentUI.INK));return;}final int[] shown={0};final TextView[] more={null};Runnable[] append={null};append[0]=()->{if(more[0]!=null)content.removeView(more[0]);int end=Math.min(text.length(),shown[0]+6000);if(end<text.length()&&Character.isHighSurrogate(text.charAt(end-1)))end--;TextView part=AgentUI.text(activity,text.substring(shown[0],end),16,AgentUI.INK);part.setTextIsSelectable(true);content.addView(part);shown[0]=end;if(end<text.length())more[0]=AgentUI.button(activity,content,"继续阅读正文（已显示 "+end+" / "+text.length()+" 字）",false,append[0]);};append[0].run();}
 private void renderAudio(AgentUI.Screen screen,LinearLayout card,MaterialCatalog catalog,MaterialCatalog.Entry entry){
  card.removeAllViews();card.addView(AgentUI.text(activity,"原音",17,AgentUI.INK));card.addView(AgentUI.text(activity,"正在读取手机已保存的原音…",13,AgentUI.MUTED));
  LifelogAudioRuntime.read(catalog.account,entry.id,(sessions,error)->{if(closed||suspended||!screen.dialog.isShowing())return;card.removeAllViews();card.addView(AgentUI.text(activity,"原音",17,AgentUI.INK));long saved=0;boolean linked=false,failed=false,running=false;for(Object raw:sessions){java.util.Map<String,Object> row=WireJson.map(raw);saved+=((Number)row.get("saved_batches")).longValue();linked|=Boolean.TRUE.equals(row.get("source_link_verified"));failed|="FAILED".equals(row.get("phase"))||"INTERRUPTED".equals(row.get("phase"));running|="RUNNING".equals(row.get("phase"));}
   String state=!error.isEmpty()?"暂时无法读取原音":sessions.isEmpty()?"尚无原音记录":saved==0?"有原音记录 · 导出时核对已保存片段":!linked?"原音已保存 · 等待关联智记":running?"原音正在保存 · 可导出已有片段":failed?"已保存部分原音 · 曾发生中断":"已保存部分原音";
   card.addView(AgentUI.text(activity,state,14,AgentUI.INK));card.addView(AgentUI.text(activity,"从手机收到音频时开始保存，可能缺少开头或断连期间的内容。导出包含音频片段和范围说明。",12,AgentUI.MUTED));
   TextView button=AgentUI.button(activity,card,"导出原音到手机",false,()->MaterialAudioExport.save(activity,catalog.account,entry));boolean enabled=error.isEmpty()&&!sessions.isEmpty()&&linked;button.setEnabled(enabled);button.setAlpha(enabled?1f:.45f);button.setContentDescription(enabled?"核对并导出已保存的原音片段到手机":"导出原音不可用："+state);
   AgentUI.button(activity,card,"导出历史远程备份到手机",false,()->MaterialAudioExport.saveRemote(activity,catalog.account,entry));AgentUI.button(activity,card,"原音与导出",false,()->AudioWorkspace.show(activity,()->{if(!closed&&!suspended&&screen.dialog.isShowing())renderAudio(screen,card,catalog,entry);}));
   AgentUI.button(activity,card,"刷新原音状态",false,()->renderAudio(screen,card,catalog,entry));card.addView(AgentUI.text(activity,"新原音只保存在手机。旧的远程备份在原保留期限内仍可导出；不再自动上传。",12,AgentUI.MUTED));
  });
 }
 private void delegate(MaterialCatalog catalog,MaterialCatalog.Entry entry,AgentUI.Screen owner){
  if(closed||suspended||openingDelegate)return;openingDelegate=true;long request=revision;TaskRuntime tasks=TaskRuntime.get(activity);
  tasks.read((state,error)->{openingDelegate=false;if(closed||suspended||request!=revision||!owner.dialog.isShowing())return;
   if(!error.isEmpty()){AgentUI.notice(activity,TaskWorkspace.label(error));return;}
   TaskWorkspace.delegateMaterial(activity,tasks,state.defaultBinding,entry,catalog.account,this::refresh);
  });
 }
 private void export(MaterialCatalog catalog,MaterialCatalog.Entry entry){OfficialLifelogInsight.Event event=snapshot==null||snapshot.insights==null?null:snapshot.insights.eventFor(entry.id,selected.toString(),snapshot.catalog.zone.getId());MaterialDocumentExport.summary(activity,catalog.account,entry,event);}
